import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"ADR-0004: Extract a dedicated blob CAS crate (historical soma-vdfs naming)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adrs/0004-vdfs-crate.md","filePath":"architecture/adrs/0004-vdfs-crate.md","lastUpdated":1780254295000}'),r={name:"architecture/adrs/0004-vdfs-crate.md"};function s(c,e,d,l,n,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0004-extract-a-dedicated-blob-cas-crate-historical-soma-vdfs-naming" tabindex="-1">ADR-0004: Extract a dedicated blob CAS crate (historical <code>soma-vdfs</code> naming) <a class="header-anchor" href="#adr-0004-extract-a-dedicated-blob-cas-crate-historical-soma-vdfs-naming" aria-label="Permalink to &quot;ADR-0004: Extract a dedicated blob CAS crate (historical `soma-vdfs` naming)&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Soma’s “blob CAS” implementation used to be duplicated in the daemon and bot binaries. It is now shared via <code>soma-vdfs</code>:</p><ul><li><code>soma_vdfs::fs::FsBlobStore</code> (<code>backend/crates/vdfs/src/fs.rs</code>)</li></ul><p>Meanwhile, the peer runtime (<code>backend/crates/peer/src/lib.rs</code>) defines the <code>BlobProvider</code> boundary and the <code>/soma/blob/1</code> protocol types. This makes it harder to:</p><ul><li>reuse the CAS implementation in other projects,</li><li>keep hashing/layout rules consistent across binaries,</li><li>evolve the blob protocol without touching multiple unrelated crates.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Create (and use) a dedicated crate for the minimal blob CAS surface (blob CAS + fetch-by-CID primitives), and make <code>soma-peer</code> depend on it.</p><p>The crate will intentionally stay narrow (no virtual filesystem mapping).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Positive:</p><ul><li>One canonical CID + layout implementation shared by daemon/bot (and other projects).</li><li>Cleaner boundaries: <code>soma-peer</code> focuses on libp2p wiring; the historical <code>soma-vdfs</code> crate focuses on CAS rules.</li><li>Reduced duplication and drift.</li></ul><p>Negative / follow-ups:</p><ul><li>Requires a small refactor to move <code>BlobProvider</code> and blob protocol types out of <code>soma-peer</code>.</li><li>May need a short compatibility phase while consumers migrate.</li></ul>',14)])])}const p=a(r,[["render",s]]);export{u as __pageData,p as default};
